const target = "62923ccda3a8bcb86b9a446feb430b7a8aa40cfd6c7b87c960a327a8b9ef72ac";
const h = s => createHash("sha256").update(s,"utf8").digest("hex");
console.log("expected:", h("quarterly-report-2026"));
console.log("target  :", target);
for (const cand of ["quarterly-report-2026","quarterly_report_2026","quarterly report 2026","quarterly_report_2026 ", " Quarterly Report 2026", "quarterly-report-2026\n", "quarterly-report-2026 ", "quarterlyreport2026","quarterly_report_2026\r", "quarterly report 2026\r", "quarterly-report-2026\u0000", "quarterly_report_2026\u0000"]) {
  if (h(cand) === target) console.log("MATCH:", JSON.stringify(cand));
}
console.log("h(lowercase no change):", h(T.toLowerCase()));
'
